<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php'; require_role('admin');
$title='Petugas';
if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM users WHERE id=? AND role<>?")->execute([(int)$_GET['delete'],'admin']);header('Location:/admin/users.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['username']),$_POST['password'],$_POST['role']];if($id){$sql="UPDATE users SET name=?,username=?,role=?";$p=[$d[0],$d[1],$d[3]];if($d[2]){$sql.=",password=?";$p[]=$d[2];}$sql.=" WHERE id=?";$p[]=$id;$pdo->prepare($sql)->execute($p);}else{$pdo->prepare("INSERT INTO users(name,username,password,role)VALUES(?,?,?,?)")->execute($d);}header('Location:/admin/users.php');exit;}
$rows=$pdo->query("SELECT id,name,username,role,created_at FROM users WHERE role<>'admin' ORDER BY id DESC")->fetchAll();require __DIR__.'/../includes/header.php';?>
<div class="d-flex justify-content-between"><h2>Petugas</h2><a class="btn btn-dark" href="?new=1">+ Tambah Petugas</a></div>
<?php if(isset($_GET['new'])): ?><div class="card my-3"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-3"><input class="form-control" name="name" placeholder="Nama" required></div><div class="col-md-3"><input class="form-control" name="username" placeholder="Username" required></div><div class="col-md-3"><input class="form-control" name="password" placeholder="Password" required></div><div class="col-md-2"><select class="form-select" name="role"><option value="cashier">Kasir</option><option value="washer">Washer</option></select></div><div><button class="btn btn-success">Simpan</button></div></form></div></div><?php endif;?>
<div class="card shadow-sm"><div class="card-body"><table class="table"><tr><th>Nama</th><th>Username</th><th>Role</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['username'])?></td><td><?=$r['role']?></td><td><a class="btn btn-sm btn-danger" onclick="return confirm('Hapus?')" href="?delete=<?=$r['id']?>">Hapus</a></td></tr><?php endforeach;?></table></div></div>
